# Project 1 preview: Simple modular math dispatcher
def calculate(op, a, b):
    ops = {'+': lambda x,y: x+y, '-': lambda x,y: x-y, '*': lambda x,y: x*y}
    if op == '/' and b == 0: return "Error: Division by zero"
    if op == '/': return a / b
    return ops.get(op, lambda x,y: "Invalid")(a, b)

print("10 / 2 =", calculate('/', 10, 2))
